const sampleBtns = SAMPLES.map((s) => `<div class="sample"><h3>${esc(s.title)}</h3><p>${s.text.split(/\s+/).length} words · fictional Harborline blog post</p><button type="button" class="use" data-id="${s.id}">Use this</button></div>`).join('');
const body = `<div class="card"><span class="st st-info">AI content repurposer</span>
<h1>One article in, a week of posts out, nothing published until you approve it</h1>
<p class="muted">Paste a blog post, a newsletter or a transcript (or give a public URL). Gemini pulls out the key points and writes a LinkedIn post, an X thread, an Instagram caption and a newsletter blurb in the voice you choose. You edit, set a date and approve each one; approved drafts land in a Google Sheets content calendar.</p>
<form method="post" action="${BASE}" id="f">
<label>Source: paste the text<textarea name="text" maxlength="20000" placeholder="Paste the article, newsletter or transcript here (at least a few paragraphs). Or leave this empty and give a URL below."></textarea></label>
<label>…or a public URL (optional)<input name="url" type="url" placeholder="https://example.com/blog/your-post" autocomplete="off"></label>
<div class="grid2">
<label>Brand voice<select name="voice">${Object.entries(VOICES).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select></label>
<div><label style="margin-bottom:6px">Platforms</label>
<label class="ck"><input type="checkbox" name="p_linkedin" value="1" checked> LinkedIn post</label>
<label class="ck"><input type="checkbox" name="p_x" value="1" checked> X / Twitter thread</label>
<label class="ck"><input type="checkbox" name="p_instagram" value="1" checked> Instagram caption</label>
<label class="ck"><input type="checkbox" name="p_newsletter" value="1" checked> Email newsletter blurb</label></div></div>
<div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div>
<button class="btn" type="submit">Write the drafts →</button>
<p class="small muted" style="margin-top:12px">Takes 10–20 seconds. Public demo: 20 runs a day. Your text is kept for 7 days so you can come back to the drafts, then deleted.</p></form></div>
<div class="card"><h2>Try it with a sample article</h2><p class="small muted">Click one to drop it into the box above (fictional posts written for this demo).</p><div class="samples">${sampleBtns}</div></div>
<div class="card"><h2>What happens when you press the button</h2><ol class="small" style="margin:0;padding-left:20px">
<li>n8n takes the text (or fetches the URL and strips it down to the article) and keeps a 7-day record.</li>
<li><b>Google Gemini</b> extracts the title, a two-line summary and the key points, then writes each platform in your voice: LinkedIn (hook, short paragraphs, 3 hashtags), X (4–7 tweets, each under 280 characters), Instagram (caption + hashtags) and a newsletter blurb (subject, preview line, body).</li>
<li>You get a page with every draft in an editable box with a character count. Edit, pick a date, press Approve: the draft goes into <b>Google Sheets</b> (Content calendar tab) with its status, and a private owner view shows what was approved for which platform.</li></ol></div>
<style>.grid2{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}@media(max-width:600px){.grid2{grid-template-columns:1fr}}.ck{display:flex!important;align-items:center;gap:8px;font-weight:500!important;margin:6px 0!important}.ck input{width:auto!important;display:inline!important}select{display:block;width:100%;padding:11px 12px;border:1px solid #c9d3e3;border-radius:10px;font:inherit;font-size:15px;background:#fff}</style>
<script>
var S = ${JSON.stringify(SAMPLES.map((s) => s.text))};
var f = document.getElementById('f');
document.querySelectorAll('button.use').forEach(function (b) { b.addEventListener('click', function () { f.text.value = S[+b.getAttribute('data-id')]; f.url.value = ''; window.scrollTo({ top: 0, behavior: 'smooth' }); f.text.focus(); }); });
f.addEventListener('submit', function () { var b = this.querySelector('button.btn'); b.textContent = 'Writing the drafts…'; b.style.opacity = '.75'; });
</script>`;
return [{ json: { html: page('AI content repurposer – Harborline Software', body) } }];

