// Validate the request, apply the public-demo limits, create the run record
const f = $json.body || {};
const h = $json.headers || {};
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (!store.day || store.day.date !== today) store.day = { date: today, count: 0, ips: {} };
store.runs = store.runs || {};
const ip = String(h['x-forwarded-for'] || h['x-real-ip'] || '').split(',')[0].trim() || 'unknown';
const text = String(f.text || '').replace(/\r\n/g, '\n').trim().slice(0, 20000);
const url = String(f.url || '').trim().slice(0, 500);
const voice = VOICES[f.voice] ? f.voice : 'professional';
const platforms = Object.keys(PLATFORMS).filter((k) => String(f['p_' + k] || '') === '1');
let problem = null;
if (f.website) problem = 'spam';
else if (!text && !url) problem = 'Please paste some text or give a URL.';
else if (!text && !/^https?:\/\/[^\s]+\.[a-z]{2,}/i.test(url)) problem = 'That does not look like a public URL. Please check it, or paste the text instead.';
else if (text && text.length < 300) problem = 'Please paste at least a few paragraphs (300 characters or more) so there is something to work with.';
else if (!platforms.length) problem = 'Please tick at least one platform.';
else if (store.day.count >= 20) problem = 'This public demo has done 20 runs today, which is its daily limit. Please try again tomorrow.';
else if ((store.day.ips[ip] || 0) >= 4) problem = 'This connection has used its 4 runs for today. Please try again tomorrow.';
if (!problem) { store.day.count += 1; store.day.ips[ip] = (store.day.ips[ip] || 0) + 1; }
const chars = 'abcdefghijkmnpqrstuvwxyz23456789';
const token = Array.from({ length: 22 }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
if (!problem) {
  const cutoff = Date.now() - 7 * 864e5;
  for (const [k, r] of Object.entries(store.runs)) if (!r || r.createdAt < cutoff) delete store.runs[k];
  const ks = Object.keys(store.runs); if (ks.length > 40) ks.sort((a, b) => store.runs[a].createdAt - store.runs[b].createdAt).slice(0, ks.length - 40).forEach((k) => delete store.runs[k]);
  const sample = SAMPLES.find((s) => text && text.startsWith(s.title));
  store.runs[token] = { token, createdAt: Date.now(), status: 'working', sourceType: text ? (sample ? 'Sample article' : 'Pasted text') : 'URL', url: text ? '' : url, title: '', words: text ? text.split(/\s+/).length : 0, voice, platforms, text: text.slice(0, 12000), drafts: null, approved: {} };
}
return [{ json: { valid: !problem, problem, token, isUrl: !problem && !text, url, voice, platforms } }];

