// Result page: the drafts for one run, each editable and approvable
const t = String(($json.query || {}).t || '').slice(0, 40);
const store = $getWorkflowStaticData('global');
const r = (store.runs || {})[t];
if (!r) return [{ json: { html: notFoundPage() } }];
if (r.status === 'working') return [{ json: { html: page('Still writing', `<div class="card"><h1>Still writing the drafts</h1><p class="muted">Refresh this page in a few seconds.</p><a class="btn" href="${BASE}/result?t=${r.token}">Refresh</a></div>`) } }];
if (r.status === 'failed') return [{ json: { html: page('Please try again', `<div class="card"><h1>The AI did not return usable drafts</h1><p class="muted">That happens now and then with long or unusual text. Please try again, or shorten the source.</p><a class="btn" href="${BASE}">Back</a></div>`) } }];
const d = r.drafts || {};
const SEP = '\n\n---\n\n';
const full = {
  linkedin: d.linkedin ? d.linkedin.text + (d.linkedin.hashtags.length ? '\n\n' + d.linkedin.hashtags.map((h) => '#' + h).join(' ') : '') : '',
  x: d.x ? d.x.tweets.join(SEP) : '',
  instagram: d.instagram ? d.instagram.caption + (d.instagram.hashtags.length ? '\n\n' + d.instagram.hashtags.map((h) => '#' + h).join(' ') : '') : '',
  newsletter: d.newsletter ? `Subject: ${d.newsletter.subject}\nPreview: ${d.newsletter.preview}\n\n${d.newsletter.body}` : '',
};
const fmt = (ms) => new Date(ms).toLocaleString('en-GB', { timeZone: 'Europe/London', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
const tomorrow = new Date(Date.now() + 864e5).toISOString().slice(0, 10);
const cards = Object.keys(PLATFORMS).filter((k) => r.platforms.includes(k)).map((k) => {
  const [name, limit, color] = PLATFORMS[k]; const a = r.approved[k]; const text = a ? a.text : full[k];
