  const extra = k === 'x' && !a ? `<div class="tweets">${d.x.tweets.map((tw, i) => `<div class="tweet"><span class="n">${i + 1}/${d.x.tweets.length} · <span class="cnt${tw.length > 280 ? ' over' : ''}">${tw.length}/280</span></span><br>${esc(tw)}</div>`).join('')}</div><p class="small muted">Edit the thread below; tweets are separated by a line with three dashes.</p>` : '';
  const status = a ? `<span class="tag good">✓ Approved · scheduled ${esc(a.date)} · in the content calendar</span>` : `<span class="tag">Draft · waiting for approval</span>`;
  return `<div class="draft" id="${k}"><div class="top"><span class="dot" style="background:${color}"></span><h3>${name}</h3>${status}<span class="cnt" data-for="t_${k}" data-limit="${limit}"></span></div>${extra}
<form method="post" action="${BASE}/approve"><input type="hidden" name="t" value="${r.token}"><input type="hidden" name="platform" value="${k}">
