// Approve one draft: store the final text and date, prepare the Google Sheets row
const f = $json.body || {};
const store = $getWorkflowStaticData('global');
const t = String(f.t || '').slice(0, 40);
const k = String(f.platform || '');
const r = (store.runs || {})[t];
if (!r || !PLATFORMS[k] || !r.platforms.includes(k)) return [{ json: { ok: false, nextUrl: BASE + (r ? '/result?t=' + t : '') } }];
if (r.approved[k]) return [{ json: { ok: false, nextUrl: `${BASE}/result?t=${t}#${k}` } }];
const text = String(f.text || '').replace(/\r\n/g, '\n').trim().slice(0, 4000);
if (text.length < 10) return [{ json: { ok: false, nextUrl: `${BASE}/result?t=${t}#${k}` } }];
const date = /^\d{4}-\d{2}-\d{2}$/.test(String(f.date || '')) ? String(f.date) : new Date(Date.now() + 864e5).toISOString().slice(0, 10);
const d = r.drafts || {}; const SEP = '\n\n---\n\n';
const original = { linkedin: d.linkedin ? d.linkedin.text + (d.linkedin.hashtags.length ? '\n\n' + d.linkedin.hashtags.map((h) => '#' + h).join(' ') : '') : '', x: d.x ? d.x.tweets.join(SEP) : '', instagram: d.instagram ? d.instagram.caption + (d.instagram.hashtags.length ? '\n\n' + d.instagram.hashtags.map((h) => '#' + h).join(' ') : '') : '', newsletter: d.newsletter ? `Subject: ${d.newsletter.subject}\nPreview: ${d.newsletter.preview}\n\n${d.newsletter.body}` : '' }[k];
const edited = text !== (original || '').trim();
r.approved[k] = { text, date, at: Date.now(), edited };
const time = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'short', timeStyle: 'short' });
const chars = k === 'x' ? `${text.split(/\n\s*---\s*\n/).length} tweets` : `${text.length} chars`;
return [{ json: { ok: true, row: [time, r.title, PLATFORMS[k][0], edited ? 'Approved (edited)' : 'Approved', date, text, chars, r.sourceType + (r.url ? ' · ' + r.url : ''), t], nextUrl: `${BASE}/result?t=${t}#${k}` } }];

// ---- shared helpers (same in every page node) ----
