const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · Content repurposer</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software is a fictional company · the sample articles are fictional, pasted text and fetched pages are used once and not stored beyond 7 days, and every draft is a suggestion for a human to approve.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that run</h1><p class="muted">The link may be old (drafts are kept for 7 days). Start a new one below.</p><a class="btn" href="${BASE}">Open the content repurposer</a></div>`);
// ---- end shared helpers ----

// Owner view: runs from the last 7 days, what was approved for which platform
const store = $getWorkflowStaticData('global');
const runs = Object.values(store.runs || {}).sort((a, b) => b.createdAt - a.createdAt);
const fmt = (ms) => new Date(ms).toLocaleString('en-GB', { timeZone: 'Europe/London', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
const drafted = runs.reduce((a, r) => a + Object.keys(r.drafts || {}).length, 0);
const approved = runs.reduce((a, r) => a + Object.keys(r.approved || {}).length, 0);
const perPlatform = Object.keys(PLATFORMS).map((k) => `${PLATFORMS[k][0].split(' ')[0]} ${runs.reduce((a, r) => a + (r.approved && r.approved[k] ? 1 : 0), 0)}`).join(' · ');
const rows = runs.map((r) => `<tr><td>${fmt(r.createdAt)}</td><td><b>${esc(r.title || '(working)')}</b><br><span class="muted small">${esc(r.sourceType)}${r.url ? ' · ' + esc(domain(r.url)) : ''} · ${r.words} words · ${esc(VOICES[r.voice] || r.voice)}</span></td><td>${Object.keys(PLATFORMS).filter((k) => (r.platforms || []).includes(k)).map((k) => `<span class="tag${r.approved && r.approved[k] ? ' good' : ''}" title="${r.approved && r.approved[k] ? 'approved for ' + esc(r.approved[k].date) : 'draft'}">${PLATFORMS[k][0].split(' ')[0]}${r.approved && r.approved[k] ? ' ✓ ' + esc(r.approved[k].date.slice(5)) : ''}</span>`).join(' ')}</td><td>${r.seconds ?? '–'} s</td><td><a href="${BASE}/result?t=${r.token}" target="_blank">drafts</a></td></tr>`).join('');
const body = `<h1>Content repurposer – owner view</h1><p class="muted">Last 7 days · ${new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' })} UK</p>
<div class="kpis"><div class="kpi"><b>${runs.length}</b>Sources</div><div class="kpi"><b>${drafted}</b>Drafts written</div><div class="kpi"><b>${approved}</b>Approved to calendar</div><div class="kpi"><b>${(store.day || {}).count || 0} / 20</b>Runs today</div></div>
<p class="small muted">Approved per platform: ${perPlatform}</p>
<div class="card" style="overflow-x:auto"><table><tr><th>When</th><th>Source</th><th>Platforms (✓ = approved, date)</th><th>Time</th><th>Open</th></tr>${rows || '<tr><td colspan="5">Nothing yet.</td></tr>'}</table></div>
<p class="small muted">Content calendar: <a href="https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit" target="_blank">Google Sheets (Content calendar tab)</a> · sources are kept 7 days; successful executions are not saved.</p>`;
return [{ json: { html: page('Content repurposer – owner view', body, true) } }];
